extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena serve un CharacterBody2D chiamato Player"):
		return

	var coyote_t = float(get_prop(player, "coyote_time", 0.0))
	var buffer_t = float(get_prop(player, "jump_buffer_time", 0.0))
	check("coyote_time_val", absf(coyote_t - 0.15) < 0.01, "coyote_time deve essere impostata a 0.15 (valore attuale: %.2f)" % coyote_t)
	check("jump_buffer_val", absf(buffer_t - 0.15) < 0.01, "jump_buffer_time deve essere impostata a 0.15 (valore attuale: %.2f)" % buffer_t)

	player.position = Vector2(400, 464)
	await wait_physics_frames(2)
	await tap_action("jump")
	var c_timer = float(get_prop(player, "coyote_timer", -1.0))
	var b_timer = float(get_prop(player, "jump_buffer_timer", -1.0))
	check("timer_coyote_zero", c_timer <= 0.0, "coyote_timer deve essere azzerato subito dopo il salto (valore attuale: %s)" % str(c_timer))
	check("timer_buffer_zero", b_timer <= 0.0, "jump_buffer_timer deve essere azzerato subito dopo il salto (valore attuale: %s)" % str(b_timer))

	player.position = Vector2(400, 300)
	player.velocity = Vector2.ZERO
	await hold_action("move_right", 2)
	check("air_movement", player.velocity.x > 0.0, "In aria il personaggio deve muoversi a destra usando air_acceleration (velocity.x è %.1f)" % player.velocity.x)

